INSERT INTO editorial.help_categories ("slug", "position", "title", "description", "icon")
VALUES
    ('getting-started', 0, 'Getting started', 'What Projective is, the three kinds of project, and your first hire or first job.', 'flag'),
    ('projects-and-stages', 1, 'Projects & stages', 'Set up a project, break it into stages and tickets, and bring people onto it.', 'stages'),
    ('escrow-and-payments', 2, 'Escrow & payments', 'How money is held before work starts, what it costs, and paying by card or wallet.', 'wallet'),
    ('revisions-and-approvals', 3, 'Revisions & approvals', 'Submitting work, asking for changes, and accepting work so payment is released.', 'submission'),
    ('disputes-and-fair-exit', 4, 'Disputes & Fair Exit', 'Ending a stage early, cancelling a session, and what happens when a session is missed.', 'shield'),
    ('payouts-and-verification', 5, 'Payouts & verification', 'Verifying who you are, when earnings become available, and withdrawing them.', 'arrow-up-right'),
    ('teams-and-businesses', 6, 'Teams & businesses', 'Working as a team of freelancers, or hiring as a business with a shared wallet.', 'members'),
    ('account-and-security', 7, 'Account & security', 'Signing in, age rules, your handle, privacy in messages and closing your account.', 'lock')
INSERT INTO editorial.help_articles ("slug", "category_slug", "position", "title", "summary", "roles", "start_here", "related", "faq_rank", "faq_question", "sections", "updated_on", "published_on", "archived_on")
VALUES
    ('what-is-projective', 'getting-started', 0, 'What is Projective?', 'Projective is a place to hire freelancers and teams, or to work as one, where every project is split into stages and the money for each stage is held safely until the work is approved.', ARRAY['client', 'freelancer', 'team', 'business']::text[], ARRAY['client', 'freelancer', 'business']::text[], ARRAY['choose-a-project-type', 'what-is-escrow', 'hire-your-first-freelancer']::text[], NULL, NULL, '[{"id":"the-idea","heading":"The idea in one minute","body":[{"type":"p","content":"Most freelance work goes wrong in the middle: the brief drifts, nobody is sure what has been paid for, and the person doing the work carries all the risk. Projective breaks every project into stages — a design stage, a build stage, a launch stage — and treats each one as its own small agreement."},{"type":"p","content":["Before work on a stage starts, the client''s money for it is put in ",{"type":"strong","text":"escrow"},": Projective holds it, and it belongs to neither side yet. When the client accepts the work, the money is released to the freelancer. Nobody works for free, and nobody pays for work they have not seen."]}]},{"id":"who-it-is-for","heading":"Who it is for","body":[{"type":"dl","items":[{"term":"Client","definition":"Anyone who hires: post a project, invite people to it, or buy a service a freelancer has packaged up."},{"term":"Freelancer","definition":"Anyone who works: apply to projects, sell services and digital products, and get paid stage by stage."},{"term":"Team","definition":"Freelancers who work together under one name, with earnings split between members automatically."},{"term":"Business","definition":"A company that hires: several colleagues share one wallet, with roles that decide who can hire and who can spend."}]},{"type":"p","content":"One account can be more than one of these. A client can become a freelancer at any time, and anyone aged 18 or over can create or join a business."}]},{"id":"what-a-stage-is-for","heading":"What every stage is for","body":[{"type":"p","content":"Each stage is labelled with what it sets out to do, so both sides agree on what “done” means:"},{"type":"list","items":["Create — making something: a design, code, copy.","Run — keeping something going: hosting, posting, monitoring.","Educate — teaching: tutoring or lessons.","Advise — guidance: a review, a strategy, a second opinion.","Test — checking something works: QA, audits, user tests.","Empower — handing over: documentation, onboarding, training."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('choose-a-project-type', 'getting-started', 1, 'Task, One-off or Pipeline: which project type fits?', 'A Task is one deliverable for one price, a One-off is a finite piece of work carried through a few milestone stages, and a Pipeline is a board of tickets for continuous work.', ARRAY['client', 'business']::text[], ARRAY['client']::text[], ARRAY['create-a-project', 'stages-and-tickets', 'what-locks-after-hiring']::text[], NULL, NULL, '[{"id":"the-three-types","heading":"The three types","body":[{"type":"table","head":["Type","Use it for","How it looks"],"rows":[["Task","One deliverable for one price — a logo, a bug fix, a short article.","One stage holding one ticket, and one shared Discussion room. No timeline or calendar."],["One-off","A finite project carried through milestones — a website in design, build and launch stages.","One master ticket moving through a run of stages, shown on a timeline."],["Pipeline","Ongoing work that keeps arriving — content production, maintenance, a product backlog.","Many tickets moving through stages on a board."]],"rowHeaders":true}]},{"id":"how-to-choose","heading":"How to choose","body":[{"type":"list","items":["If you can describe the whole job in one sentence and pay for it once, choose a Task.","If the job has a clear end but happens in steps you want to approve one at a time, choose a One-off.","If you will keep adding work for weeks or months, choose a Pipeline."]},{"type":"callout","tone":"note","title":"Sessions are sold, not posted","body":[{"type":"p","content":"Live calls, lessons and consultations are sessions. A freelancer packages them as a service, and you book them from their listing — you do not create a session project yourself."}]}]},{"id":"changing-your-mind","heading":"Changing your mind later","body":[{"type":"p","content":["You can change a project''s type while you are setting it up. Once the first freelancer has joined, the type is fixed, because they agreed to that shape of work. See ",{"type":"link","href":"/help/projects-and-stages/what-locks-after-hiring","text":"what you can still change after someone is hired"},"."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('hire-your-first-freelancer', 'getting-started', 2, 'How hiring works: invitations, applications and calls', 'You can invite someone you found on Explore, accept a freelancer who applied to your project, or book a short call first — and every hire is agreed one stage at a time.', ARRAY['client', 'business']::text[], ARRAY['client']::text[], ARRAY['invite-people-to-a-stage', 'how-stage-funding-works', 'create-a-project']::text[], NULL, NULL, '[{"id":"three-ways-in","heading":"Three ways to start","body":[{"type":"h3","text":"Invite someone","id":"invite-someone"},{"type":"p","content":"Find a freelancer or a team on Explore and invite them to a stage of your project. If you wrote an introduction, it opens a conversation with them; they accept or decline the stage."},{"type":"h3","text":"Accept an application","id":"accept-an-application"},{"type":"p","content":"Once your project is published, freelancers can apply to its stages with a short note. You''ll find every application under Requests on the project''s Members page, with Accept and Reject on each."},{"type":"h3","text":"Talk first","id":"talk-first"},{"type":"p","content":"Many freelancers offer a free courtesy call on their availability page. It is just a conversation: it creates no project, holds no money and commits nobody to anything."}]},{"id":"one-stage-at-a-time","heading":"Hiring happens one stage at a time","body":[{"type":"p","content":"Joining a project never puts someone on every stage. A freelancer holds exactly the stages they were invited to and accepted, at the price set for each stage — so you can bring in a designer for the design stage and a developer for the build."}]},{"id":"fair-play","heading":"Fair-play limits","body":[{"type":"list","items":["If someone declines your invitation, you can''t invite them to the same project again for 48 days.","You can send up to 10 invitations in any 10 minutes, across all your projects.","Freelancers'' proposals are paced with a weekly allowance, so the same few people can''t apply to everything — which makes your shortlist better."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('start-working-as-a-freelancer', 'getting-started', 3, 'Start working as a freelancer', 'Unlock a freelancer profile from Become a Freelancer, finish the basics of your profile, and get payout-ready — you need a verified identity and payout account before you can take paid work.', ARRAY['freelancer', 'team']::text[], ARRAY['freelancer', 'team']::text[], ARRAY['get-payout-ready', 'claim-and-start-a-ticket', 'create-a-team']::text[], NULL, NULL, '[{"id":"unlock-the-profile","heading":"Unlock your freelancer profile","body":[{"type":"p","content":["If you signed up to hire, you can still work: open ",{"type":"link","href":"/become-partner","text":"Become a Freelancer"}," from the account menu. It is free, and you pick between one and ten starting skills. Your reviews and reputation stay with the same account, and you switch between hiring and working from the account menu."]}]},{"id":"go-live","heading":"Reach the go-live milestone","body":[{"type":"p","content":"Your profile can go public once it has a photo, a headline, a short story about you and at least three skills. That is enough to publish services and apply to work, even before every section is complete."},{"type":"p","content":"The ring around your avatar in the account menu shows how complete your profile is, and lists the steps left."}]},{"id":"get-paid","heading":"Get ready to be paid","body":[{"type":"callout","tone":"important","title":"Payout-ready before you earn","body":[{"type":"p","content":["Before you can apply for paid work, accept an invitation, claim a ticket or join a team, you need a verified identity and a verified payout account. Set both up in ",{"type":"link","href":"/settings/verification","text":"Settings → Verification & payouts"},". This is what guarantees that money held for you can always be paid out."]}]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('create-a-project', 'projects-and-stages', 0, 'Create a project and set it up', 'Start with a title, a type, a currency and an optional price; Projective creates a draft with its first stage, and you finish the brief, the stages and the terms on the project''s setup page before publishing.', ARRAY['client', 'business']::text[], '{}'::text[], ARRAY['choose-a-project-type', 'stages-and-tickets', 'what-locks-after-hiring']::text[], NULL, NULL, '[{"id":"quick-start","heading":"Step 1: the quick start","body":[{"type":"p","content":["Choose ",{"type":"strong","text":"Create project"}," on your Projects page. The window asks for only four things:"]},{"type":"list","ordered":true,"items":["A title of at least three characters.","The project type — Task, One-off or Pipeline.","The currency. It is fixed to the project, because escrow is priced in it.","Optionally, one price: a pipeline''s usual ticket rate, or the budget of a one-off or Task."]},{"type":"p","content":"That creates a private draft with its first stage already in place, and takes you straight to its setup page. Nothing is published yet."}]},{"id":"set-it-up","heading":"Step 2: set it up","body":[{"type":"p","content":"The setup page is one long page with a section list beside it, not a step-by-step wizard, so you can fill it in any order. It covers the brief, who owns the work you receive, visibility, deadline bonuses, reference files, an NDA, and each stage''s scope, tasks, skills, duration and seats."},{"type":"image","src":"https://placehold.co/1200x675?text=Project+setup+page","alt":"The project setup page: a section list on the left and the brief, stages and terms on the right.","w":1200,"h":675,"caption":"The setup page lists its sections beside the form."},{"type":"p","content":"A progress ladder shows how far along you are. You can preview the project as a freelancer will see it once the essentials are there: the title, the type, pricing and who you need."}]},{"id":"publish","heading":"Step 3: publish","body":[{"type":"p","content":"Publishing takes the project live. Before it does, a confirmation tells you exactly what will lock once someone is hired, so nothing changes under anyone''s feet later."},{"type":"callout","tone":"tip","title":"Just organising your own work?","body":[{"type":"p","content":"Choose Personal project when you create it. A personal project has stages, tickets, a board and files, but no money and no members — it is a planning tool that stays private."}]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('stages-and-tickets', 'projects-and-stages', 1, 'Stages and tickets, explained', 'A stage is a step of the project that is funded, delivered and approved on its own; a ticket is one piece of work inside it that a freelancer claims, completes and submits.', ARRAY['client', 'freelancer', 'team', 'business']::text[], '{}'::text[], ARRAY['claim-and-start-a-ticket', 'how-stage-funding-works', 'submit-work-for-review']::text[], NULL, NULL, '[{"id":"stages","heading":"Stages","body":[{"type":"p","content":"A stage is the unit money moves in. Its tickets are paid for before work starts, and the stage closes when its work is approved and paid. You can add, rename, reorder and remove stages as the project changes."},{"type":"p","content":"Reordering stages never reshuffles the tickets inside them. Removing a stage that holds claimed, funded work releases that money to the freelancer doing it — the same as removing the ticket."}]},{"id":"tickets","heading":"Tickets","body":[{"type":"p","content":"A ticket needs only a title to exist, so you can sketch the work quickly. It needs a description before anyone can pay for it, because a freelancer has to know what they are agreeing to."},{"type":"list","items":["You can edit a ticket until a freelancer claims it. After that its title, description and price are locked.","You can move a ticket between stages until a freelancer is working on it. Moving it then would change the work they agreed to, so it waits until the work is handed back for review.","Freelancers only ever see tickets that are paid for in the stage they sit in."]}]},{"id":"the-board","heading":"The board","body":[{"type":"p","content":"Each stage has a board with columns for every step a ticket goes through. Clients can follow progress there without interrupting the work. In a New column you can drag tickets into the order you want; after that, tickets sort by their latest update."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('invite-people-to-a-stage', 'projects-and-stages', 2, 'Invite people to a stage', 'Invite a freelancer or team to a stage from the project''s Members page or a shared invite link; they accept or decline each stage, and someone who declines can''t be re-invited to that project for 48 days.', ARRAY['client', 'business']::text[], ARRAY['business']::text[], ARRAY['hire-your-first-freelancer', 'what-locks-after-hiring', 'create-a-business']::text[], NULL, NULL, '[{"id":"send-an-invitation","heading":"Send an invitation","body":[{"type":"p","content":"Open the project''s Members page and choose Invite. Search for a person or a team, or pick from Quick add — the people you already work with. You can also type an email address to invite someone who isn''t on Projective yet."},{"type":"p","content":"Each invitation is for one stage at that stage''s price. To give a member another stage, use Invite to stage on their card; they accept or decline it like any other invitation."}]},{"id":"invite-links","heading":"Share an invite link","body":[{"type":"p","content":"Every stage can have one invite link to share by email, WhatsApp, LinkedIn or X. Opening it asks the person to sign in and offers Ask to join. A link never puts anyone on the stage by itself: it files a request you accept or decline. You can reset the link (the old one stops working at once) or turn it off."}]},{"id":"after-you-send","heading":"After you send","body":[{"type":"p","content":"The Invitations section shows each invitation as Pending, Accepted, Declined or Expired. You can cancel an open one, dismiss a declined or expired one, and remove someone who joined."},{"type":"callout","tone":"warning","title":"Saying no once is enough","body":[{"type":"p","content":"If someone declines, the invite control for them on that project shows a lock and the date it reopens, 48 days after their decline. Dismissing the declined invitation doesn''t shorten the wait. You can also send at most 10 invitations in any 10 minutes."}]},{"type":"p","content":"The project''s owner can let an admin or manager invite people and answer requests on their behalf. Appointing admins and removing people stay with the owner."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('claim-and-start-a-ticket', 'projects-and-stages', 3, 'Claiming a ticket and starting work', 'Claiming a ticket is what holds its money in escrow, so you only ever start work that is already paid for; if the money can''t be held, the claim is refused and the client is asked to fund it.', ARRAY['freelancer', 'team']::text[], ARRAY['freelancer', 'team']::text[], ARRAY['needs-funding', 'submit-work-for-review', 'get-payout-ready']::text[], NULL, NULL, '[{"id":"claiming","heading":"What claiming does","body":[{"type":"p","content":"On a stage you''re part of, drag a ticket into the work column or choose Claim. The ticket''s escrow is held at that moment — or, if the client already paid for it in advance, the claim simply names you as the person to be paid."},{"type":"p","content":"You''re told “Funded — you can start” as soon as the money is held."}]},{"id":"no-hold-no-work","heading":"No hold, no work","body":[{"type":"p","content":["If the money can''t be held — the ticket has no price, or the client''s wallet can''t cover it — the claim is refused and the ticket moves to ",{"type":"strong","text":"Needs funding"},". It leaves every freelancer''s board until the client pays, and the client is told why."]},{"type":"p","content":"The board shows the work columns as locked while you drag a claimed ticket that isn''t funded, with the reason, rather than letting you drop it somewhere it can''t go."}]},{"id":"before-you-can-claim","heading":"Before you can claim","body":[{"type":"p","content":["You need to be on the stage and payout-ready. ",{"type":"link","href":"/help/payouts-and-verification/get-payout-ready","text":"Here''s how to get payout-ready"},"."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('what-locks-after-hiring', 'projects-and-stages', 4, 'What you can still change after someone is hired', 'Once a freelancer joins, the project''s type is fixed and each staffed stage''s ticket price is frozen; scope, checklists, skills and notes stay editable.', ARRAY['client', 'business']::text[], '{}'::text[], ARRAY['create-a-project', 'stages-and-tickets', 'choose-a-project-type']::text[], NULL, NULL, '[{"id":"what-locks","heading":"What locks, and when","body":[{"type":"table","head":["What","Locks when"],"rows":[["The project type","The first freelancer joins anywhere on the project."],["A stage''s ticket price","That stage is staffed. Other stages can still be repriced."],["The single price of a Task or flat One-off","Anyone joins the project, since they were hired against that price."]],"rowHeaders":true},{"type":"p","content":"These are the terms a freelancer accepted, so they can''t change once the work is agreed. A seat someone took stays counted even if they later leave. A declined invitation never locks anything."}]},{"id":"what-stays-editable","heading":"What stays editable","body":[{"type":"p","content":"Scope, the task checklist, required skills and delivery notes can always be clarified — that helps the people doing the work. If you accept someone while the project is still a draft, nothing locks until you publish."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('what-is-escrow', 'escrow-and-payments', 0, 'What escrow means on Projective', 'Escrow is money Projective holds for a piece of work: the client pays it in before the work starts, and it is released to the freelancer only when the work is approved — or refunded if it never happens.', ARRAY['client', 'freelancer', 'team', 'business']::text[], '{}'::text[], ARRAY['how-stage-funding-works', 'accept-and-release-payment', 'fees']::text[], 1, 'Is my money safe before the work is done?', '[{"id":"held-by-projective","heading":"Held by Projective, owned by neither side","body":[{"type":"p","content":"While money is in escrow it belongs to neither the client nor the freelancer: Projective''s ledger holds it against one specific ticket or session. That protects both people — the freelancer knows the money exists before they start, and the client knows it only moves when they approve the work."}]},{"id":"when-it-is-held","heading":"When money goes in, and when it comes out","body":[{"type":"table","head":["Project type","Held","Released"],"rows":[["Task and One-off","Up front, when the stage begins (or earlier, if the client prepays).","When the client approves the work."],["Pipeline","When a freelancer claims a ticket at the latest — or earlier, if the client prepays.","When the client approves the ticket''s work on that stage."],["Session","When the booking is paid.","Automatically 24 hours after the session ends, unless a no-show is reported."]],"rowHeaders":true}]},{"id":"no-hold-no-work","heading":"No hold, no work","body":[{"type":"p","content":["A freelancer can only start a ticket whose money is already held. If it can''t be held, the ticket waits as ",{"type":"link","href":"/help/escrow-and-payments/needs-funding","text":"Needs funding"}," until the client pays. Nobody is ever asked to work on a promise."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('how-stage-funding-works', 'escrow-and-payments', 1, 'How stage funding works', 'You pay for a stage — or a single ticket — before the work starts, from your wallet or by card; the money is held in escrow and goes to whoever is hired to do it, or comes back to you in full if nobody does.', ARRAY['client', 'business']::text[], ARRAY['client', 'business']::text[], ARRAY['what-is-escrow', 'needs-funding', 'paying-by-card-and-currencies']::text[], 2, 'When do I pay, and for what?', '[{"id":"fund-a-stage","heading":"Fund a whole stage","body":[{"type":"p","content":["On a stage''s board, a line tells you how many tickets need money to start and how much. Choose ",{"type":"strong","text":"Fund stage"}," to pay for every ticket in it that nobody has paid for yet. You can fund a stage while it is open, assigned or already in progress."]},{"type":"image","src":"https://placehold.co/1200x675?text=Fund+stage+dialog","alt":"The Fund stage dialog: the stage name, the total to hold, the number of tickets, and a choice between paying from the wallet or by card.","w":1200,"h":675,"caption":"Fund stage shows the exact amount to hold before you pay."},{"type":"list","items":["From wallet — offered when your wallet''s available balance covers the stage.","By card — always offered. The card payment arrives in your wallet and is held from there."]},{"type":"p","content":"Every ticket in the stage needs a price first. If one doesn''t have one, the dialog says so and nothing is charged."}]},{"id":"fund-one-ticket","heading":"Fund one ticket","body":[{"type":"p","content":"Buy Now on a ticket pays for that ticket alone, by card or from your wallet. To pay for several at once, add them to your basket — the board''s Checkout button adds every unfunded ticket — and pay in one go."}]},{"id":"who-gets-it","heading":"Who the money goes to","body":[{"type":"p","content":"Money you pay before anyone is hired is held with no payee yet. The freelancer who claims the ticket becomes its payee, without you being charged again, and they''re told they can start."},{"type":"callout","tone":"note","title":"Prepaid money nobody claimed comes back","body":[{"type":"p","content":"If a prepaid ticket is completed, removed or cancelled without anyone claiming it — or you approve the stage while it is still unclaimed — its money is refunded to you in full. Prepaid escrow is never paid to nobody."}]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('fees', 'escrow-and-payments', 2, 'Fees: the 5% service fee and card processing', 'Projective keeps a 5% service fee from each payment when its escrow is released to the freelancer; clients pay the listed price, and card processing is a separate cost you can choose to help cover.', ARRAY['client', 'freelancer', 'team', 'business']::text[], '{}'::text[], ARRAY['what-is-escrow', 'the-7-day-pending-window', 'paying-by-card-and-currencies']::text[], 3, 'What does Projective charge?', '[{"id":"the-service-fee","heading":"The 5% service fee","body":[{"type":"p","content":"When escrow is released, 5% of the released amount is kept as Projective''s service fee and the rest goes to the freelancer or team. It pays for holding the money, running payments and handling disputes."},{"type":"table","head":["Step","Amount"],"rows":[["The client pays into escrow","£1,000.00"],["Service fee (5%)","£50.00"],["The freelancer receives","£950.00"]],"caption":"A £1,000 stage, approved","rowHeaders":true},{"type":"list","items":["The fee is worked out in whole pennies and rounded down, so it is never more than 5%.","A deadline bonus is paid on top of the escrow, with no fee taken from it.","In a Fair Exit, the fee is charged only on the share the freelancer earned; the refunded part comes back to the client without a fee.","Your plan never changes the fee. Only an approved volume contract with an enterprise or business can."]}]},{"id":"card-processing","heading":"Card processing","body":[{"type":"p","content":["Card networks charge to process a card payment, and that cost isn''t part of the 5%. At card checkout you can tick ",{"type":"strong","text":"Help cover the card processing fee"}," to add it to your total. It is never ticked for you, and it isn''t offered when you pay from your wallet, because then no card is involved."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('needs-funding', 'escrow-and-payments', 3, 'Why a ticket says Needs funding', 'Needs funding means a ticket was ready to start but its money couldn''t be held — usually because the paying wallet was short or the ticket has no price — so it waits, off freelancers'' boards, until the client pays.', ARRAY['client', 'freelancer', 'business']::text[], '{}'::text[], ARRAY['how-stage-funding-works', 'claim-and-start-a-ticket', 'approve-a-stage']::text[], NULL, NULL, '[{"id":"what-it-means","heading":"What it means","body":[{"type":"p","content":"A ticket''s escrow is held at a fixed moment — when it is claimed, or for a Pipeline''s next stage when the previous one is approved. If the money can''t be held then, the ticket moves to Needs funding instead of starting. Common reasons:"},{"type":"list","items":["The paying wallet doesn''t have enough available money.","The ticket or its stage has no price.","For a business, the payment needs a spending approval first."]}]},{"id":"what-to-do","heading":"What to do","body":[{"type":"p","content":"If you''re the client, you''ll have been told the reason and the amount. Fund the ticket from your wallet or pay by card with Buy Now, and the freelancer is told they can start. If you''re the freelancer, there''s nothing to do: the ticket comes back to your board once it is funded."}]},{"id":"pipelines","heading":"Pipelines: funding on arrival","body":[{"type":"p","content":"When you approve a Pipeline ticket''s work on one stage, that stage is paid and the ticket moves to its next stage. With Fund on arrival on (the default), the next stage''s money is held straight away from your wallet''s current balance. If it can''t be, the approval still stands — the finished stage is still paid — and the ticket waits as Needs funding. You can turn Fund on arrival off for a stage in its advanced settings; the ticket then waits there unfunded until you pay by hand."},{"type":"callout","tone":"tip","title":"Businesses can fund automatically","body":[{"type":"p","content":"A business can choose what happens when one of its tickets needs funding: tell the project owner, add the ticket to their basket, or pay it from the business wallet as soon as the wallet can cover it."}]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('paying-by-card-and-currencies', 'escrow-and-payments', 4, 'Paying by card, wallet and in other currencies', 'Individuals can pay by card with no ID checks or setup; you''re charged in the currency the seller priced in, with your own currency shown beside it, and a payment that can''t complete is kept in your wallet.', ARRAY['client', 'business']::text[], '{}'::text[], ARRAY['how-stage-funding-works', 'fees', 'business-wallet-and-spending-limits']::text[], NULL, NULL, '[{"id":"pay-by-card","heading":"Pay by card with nothing to set up","body":[{"type":"p","content":"Buying never needs an identity check or a wallet set-up. Pay by card through Stripe, and save the card for next time if you like. Apple Pay, Google Pay and PayPal appear as quick buttons where your device supports them."},{"type":"p","content":"Behind the scenes a card payment is paid into a wallet Projective opens for you, and the purchase is paid from there — so card and wallet payments are one record. If what you paid for can no longer go ahead (the price changed, or the stage moved on), the money stays in your wallet and you''re told why. A payment that arrives is never lost."}]},{"id":"currencies","heading":"Currencies","body":[{"type":"p","content":"Everything is priced and paid in the currency its creator chose. You can browse in your own currency (Settings → Language & region), and checkout shows both figures — for example, your currency''s total beside the exact amount charged in the seller''s — with the rate used. Your bank converts the charge on your statement."},{"type":"p","content":"The rate is captured at the moment money is committed, so a settled amount never drifts with the market afterwards."}]},{"id":"paying-as-a-business","heading":"Paying as a business","body":[{"type":"p","content":["A business pays from its own wallet or with a card saved to the business — never with a member''s personal card. If the business wallet is short, the payment is refused and members who can add money are offered ",{"type":"strong","text":"Contribute"},"."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('submit-work-for-review', 'revisions-and-approvals', 0, 'Submitting work for review', 'Create a submission on the stage, add your files, and send it to the client with Submit for Review; it stays In Review until the client accepts it or asks for a revision.', ARRAY['freelancer', 'team']::text[], ARRAY['freelancer']::text[], ARRAY['accept-and-release-payment', 'free-and-paid-revisions', 'the-7-day-pending-window']::text[], NULL, NULL, '[{"id":"make-a-submission","heading":"Make a submission","body":[{"type":"list","ordered":true,"items":["Open the stage''s Submissions view and choose Create New Submission.","Upload the files that prove the work, or add them from your files. Some stages only need a screenshot or a short note rather than finished files.","Choose Submit for Review, check what you are sending, then Confirm & Submit to Client."]},{"type":"image","src":"https://placehold.co/1200x675?text=Submit+for+review","alt":"The submit-for-review confirmation listing the files about to be sent to the client.","w":1200,"h":675}]},{"id":"after-you-submit","heading":"After you submit","body":[{"type":"dl","items":[{"term":"In Review","definition":"The client has it. Nothing more is needed from you yet."},{"term":"Revision Requested","definition":"The client asked for changes. The ticket comes back to you with their notes; submit again when it is ready."},{"term":"Approved","definition":"The client accepted it and the ticket''s payment was released to you. It clears the 7-day pending window, then you can withdraw it."}]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('accept-and-release-payment', 'revisions-and-approvals', 1, 'Accept & release payment', 'When you accept a submission, that ticket''s escrow is released to the freelancer straight away, less the 5% service fee — so Projective asks you to confirm first, because it can''t be undone.', ARRAY['client', 'business']::text[], ARRAY['client']::text[], ARRAY['approve-a-stage', 'free-and-paid-revisions', 'fees']::text[], 4, 'When does the freelancer get paid?', '[{"id":"accepting","heading":"Accepting a submission","body":[{"type":"p","content":["Open the submission and review the work against the stage''s checklist. If it is done, choose ",{"type":"strong","text":"Accept & release payment"},". A short confirmation explains that accepting releases this ticket''s escrow to the freelancer now; choose Accept & release to go ahead, or Not yet to keep reviewing."]},{"type":"p","content":"The ticket completes and the money goes to the freelancer — or, for a team, is split between its members by their agreement."}]},{"id":"not-ready","heading":"If it isn''t ready","body":[{"type":"p","content":["Choose Request revision instead and say what needs to change. The ticket goes back to the freelancer and no money moves. ",{"type":"link","href":"/help/revisions-and-approvals/free-and-paid-revisions","text":"How many revisions you get"}," depends on the service you bought."]}]},{"id":"for-the-freelancer","heading":"What the freelancer sees","body":[{"type":"p","content":"The freelancer is told the work was accepted. Their earnings show as Pending for 7 days and then become Available to withdraw."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('approve-a-stage', 'revisions-and-approvals', 2, 'Approving a stage', 'Approve Stage pays out any money still held on the stage and closes it; prepaid tickets nobody claimed are refunded to you, and a stage nobody was hired on can''t be approved.', ARRAY['client', 'business']::text[], '{}'::text[], ARRAY['accept-and-release-payment', 'needs-funding', 'end-a-stage-with-fair-exit']::text[], NULL, NULL, '[{"id":"what-it-does","heading":"What Approve Stage does","body":[{"type":"p","content":"Once a stage''s work is accepted, Approve Stage settles it: any escrow still held for the people hired on it is released to them, and the stage closes. If every ticket was already paid when you accepted it, approving simply closes the stage."},{"type":"p","content":"It always asks first — “Approve stage and release payment?” — because the money it releases can''t come back."}]},{"id":"edge-cases","heading":"Unclaimed tickets and empty stages","body":[{"type":"list","items":["A ticket you prepaid that nobody claimed is refunded to you in full and stays open, rather than being marked done.","A stage nobody was ever hired on can''t be approved — there is no one to pay. Its prepaid money waits for a freelancer to claim a ticket."]}]},{"id":"pipelines","heading":"On a Pipeline","body":[{"type":"p","content":["Approving a Pipeline ticket''s work on one stage moves it to its next stage, and — with Fund on arrival on — holds that stage''s money from your wallet straight away. If the wallet is short, the ticket waits as ",{"type":"link","href":"/help/escrow-and-payments/needs-funding","text":"Needs funding"},"; the stage you approved is still paid."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('free-and-paid-revisions', 'revisions-and-approvals', 3, 'Free and paid revisions', 'A stage bought from a service comes with the free revision rounds its listing promised; after those, you can buy one extra round at a time at the listing''s price, and the work goes back only once that round is paid.', ARRAY['client', 'freelancer', 'business']::text[], '{}'::text[], ARRAY['accept-and-release-payment', 'submit-work-for-review', 'fees']::text[], 5, 'How many revisions do I get?', '[{"id":"your-allowance","heading":"Your free rounds","body":[{"type":"p","content":"When a project is created from a freelancer''s service, each stage copies that service''s revision terms: how many free rounds you get, and what an extra round costs. Those terms are then fixed — a later price change on the listing doesn''t affect what you bought."},{"type":"p","content":"A stage you wrote yourself, rather than bought from a listing, has unlimited free revisions. On a bought stage each round you ask for is counted, so you can see how many of your free rounds you have used."}]},{"id":"buying-a-round","heading":"Buying an extra round","body":[{"type":"p","content":["Once the free rounds are used, Request revision becomes ",{"type":"strong","text":"Buy a revision"}," with its price. You can pay three ways:"]},{"type":"list","items":["Pay from wallet — from your available balance (not money still clearing).","Pay by card.","Add to basket, to pay alongside other things."]},{"type":"p","content":"The payment is held in escrow on the ticket like any other, and released when you approve the revised work. The work goes back to the freelancer only once the round is paid, and they are told “Paid revision, funded, you can start.” A bought round doesn''t use up a free one."},{"type":"callout","tone":"note","body":[{"type":"p","content":"If the listing set the extra-round price to zero, extra rounds stay free. If it never set a price, extra rounds can''t be bought and the work can''t be sent back again after the free rounds."}]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('end-a-stage-with-fair-exit', 'disputes-and-fair-exit', 0, 'End a stage early with Fair Exit', 'Fair Exit ends a stage that can''t be finished: you choose to pay the freelancer 25%, 50% or 75% of the money held, see the exact split before you confirm, and the rest comes back to you.', ARRAY['client', 'business', 'freelancer']::text[], ARRAY['client']::text[], ARRAY['how-disputes-are-decided', 'approve-a-stage', 'fees']::text[], 6, 'What if I need to end a stage early?', '[{"id":"when-to-use-it","heading":"When to use it","body":[{"type":"p","content":"Sometimes a stage can''t be finished — plans change, or the work and the brief have drifted too far apart. Fair Exit closes the stage and divides the money held for it so that the time already put in is paid and the rest is returned."},{"type":"p","content":"Whoever reviews the project''s work (the owner, or someone on the client side with that permission) can end a stage. A freelancer who wants to stop should talk to the client first, or contact support."}]},{"id":"how-it-works","heading":"How it works","body":[{"type":"list","ordered":true,"items":["In the stage''s Submissions view, choose End Stage (Fair Exit).","Pick how much of the held money the freelancer earned: 25%, 50% or 75%.","Read the preview: what is paid to the freelancer, the platform fee on that share, and what is refunded to you.","Confirm. It can''t be undone."]},{"type":"image","src":"https://placehold.co/1200x675?text=Fair+Exit+preview","alt":"The Fair Exit dialog with 25, 50 and 75 percent options and the amounts paid to the freelancer, kept as a fee and refunded to the client.","w":1200,"h":675,"caption":"Every figure in the preview is exactly what will move."}]},{"id":"what-happens-next","heading":"What happens next","body":[{"type":"list","items":["The 5% fee is charged only on the freelancer''s share; your refund comes back without a fee.","Money you prepaid for tickets nobody claimed comes back to you whole.","The stage''s remaining tickets close as cancelled, and both sides are told what moved.","For a team, the freelancer''s share is split between members by their agreement."]},{"type":"p","content":"A stage that is already settled, or that has no money held, can''t be ended this way; the dialog says so."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('session-cancellations', 'disputes-and-fair-exit', 1, 'Cancelling a session: the 24-hour rule', 'Cancel more than 24 hours before a session and you''re refunded in full; cancel later and the payment goes to the freelancer for the time they kept free. If the freelancer cancels, you''re always refunded.', ARRAY['client', 'freelancer']::text[], '{}'::text[], ARRAY['report-a-session-no-show', 'what-is-escrow', 'the-7-day-pending-window']::text[], NULL, NULL, '[{"id":"the-rule","heading":"The rule","body":[{"type":"table","head":["What happens","When","The money"],"rows":[["You cancel","More than 24 hours before","Refunded to you in full."],["You cancel","Less than 24 hours before","Paid to the freelancer."],["The freelancer cancels","Any time","Refunded to you in full, at once."],["The session happens","—","Paid to the freelancer 24 hours after it ends, unless a no-show is reported."]],"rowHeaders":true}]},{"id":"blocks-of-sessions","heading":"Blocks of sessions","body":[{"type":"p","content":"A block of one-to-one sessions holds a separate payment for each sitting, and the rule applies to each one on its own. Cancelling a block can therefore refund the sittings more than 24 hours away while paying for those inside the window. A sitting that has already started is never pulled back into a cancellation."},{"type":"p","content":"When you buy a block you pick the first time; the rest are pencilled in a week apart. The freelancer proposes times that suit you both, and each pencilled-in time should be agreed within 72 hours of paying. If it isn''t, the pencilled-in time stands."},{"type":"p","content":"A seat in a group session is one payment for the whole course, timed from its first sitting and paid out after its last."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('report-a-session-no-show', 'disputes-and-fair-exit', 2, 'Report a session no-show', 'If the freelancer didn''t turn up, report a no-show from the session''s sidebar; the sitting''s payment is held while the room''s attendance is checked, and a missed session is refunded automatically.', ARRAY['client']::text[], '{}'::text[], ARRAY['how-disputes-are-decided', 'session-cancellations', 'what-is-escrow']::text[], NULL, NULL, '[{"id":"report-it","heading":"Report it","body":[{"type":"p","content":["Open the session''s project. Under ",{"type":"strong","text":"No-show claims"}," in its sidebar, choose Report no-show on the sitting, add a short reason if you like, and confirm. Only an attendee can report a no-show."]},{"type":"p","content":"The sitting''s payment is held from that moment, so it can''t be paid out automatically while the claim is open."}]},{"id":"how-it-is-decided","heading":"How it is decided","body":[{"type":"p","content":"When the sitting ends, its room''s attendance log is checked:"},{"type":"list","items":["The freelancer never joined — you are refunded at once.","You and the freelancer were both in the room for at least 80% of the session — the claim is dismissed and the freelancer is paid.","Anything else, including a meeting link that isn''t tracked — the freelancer is asked to respond within 48 hours, and then a Projective auditor decides."]},{"type":"p","content":["You can follow the claim with View case. ",{"type":"link","href":"/help/disputes-and-fair-exit/how-disputes-are-decided","text":"Here''s what each stage of a case means"},"."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('how-disputes-are-decided', 'disputes-and-fair-exit', 3, 'How a dispute is decided', 'A dispute moves from Claim open to Awaiting response to Under review, and ends Released, Refunded or Split; both sides can file statements and evidence, nothing in a case can be edited or deleted, and an auditor''s ruling is final on Projective.', ARRAY['client', 'freelancer', 'team']::text[], '{}'::text[], ARRAY['report-a-session-no-show', 'end-a-stage-with-fair-exit', 'session-cancellations']::text[], NULL, NULL, '[{"id":"the-stages-of-a-case","heading":"The stages of a case","body":[{"type":"dl","items":[{"term":"Claim open","definition":"The claim is filed and the payment is held. The room''s attendance is checked when the session ends."},{"term":"Awaiting response","definition":"The logs didn''t settle it. The freelancer has 48 hours to give their account and any evidence."},{"term":"Under review","definition":"A Projective auditor is reviewing everything. The payment stays held until they rule."},{"term":"Released · Refunded · Split","definition":"The ruling: the payment goes to the freelancer, back to the client, or is divided between you."}]}]},{"id":"evidence","heading":"Statements and evidence","body":[{"type":"p","content":"While a case is live, both sides can write a statement and attach files from the case. Statements and files are kept exactly as filed: nobody can edit or delete them, and a file filed as evidence can''t be removed from your library while the case is open. Either side can send a case waiting for a response to an auditor straight away rather than wait for the 48 hours."}]},{"id":"deliverable-work","heading":"Disagreements about deliverable work","body":[{"type":"p","content":["Formal cases cover session attendance today. For a stage of deliverable work, talk it through in the stage''s discussion first; if it can''t be finished, the client can end it with ",{"type":"link","href":"/help/disputes-and-fair-exit/end-a-stage-with-fair-exit","text":"Fair Exit"},". If you can''t agree, contact support and tell us the project and stage."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('get-payout-ready', 'payouts-and-verification', 0, 'Get payout-ready: identity and payout account', 'To take paid work you need two things in Settings → Verification & payouts: an identity check with Stripe and a verified payout account. Clients who only buy never need either.', ARRAY['freelancer', 'team']::text[], ARRAY['freelancer', 'team']::text[], ARRAY['the-7-day-pending-window', 'withdraw-your-earnings', 'start-working-as-a-freelancer']::text[], 7, 'Why do I need to verify my identity to work?', '[{"id":"the-two-steps","heading":"The two steps","body":[{"type":"list","ordered":true,"items":[{"content":[{"type":"strong","text":"Verify your identity."}," Stripe checks a government ID and takes a quick selfie to confirm it''s you. Projective never stores your documents — only Stripe''s reference to the check."]},{"content":[{"type":"strong","text":"Set up payouts."}," Add the bank account your earnings will be paid into, through Stripe. It is verified before it can receive money."]}]},{"type":"p","content":["Both live in ",{"type":"link","href":"/settings/verification","text":"Settings → Verification & payouts"},", which shows what is done and the one next step."]}]},{"id":"why-before-work","heading":"Why it comes before the work","body":[{"type":"p","content":"Projective checks this before you earn, not when you withdraw: you can''t apply for paid work, accept an invitation, claim or be assigned a ticket, or create or join a team until both steps are done. That way, money held for you can always be paid out — it can never get stuck in escrow with nobody able to receive it."},{"type":"callout","tone":"note","title":"Teams","body":[{"type":"p","content":"A team is seated on new work only when everyone who receives a share of its earnings is payout-ready. A team already working on a stage keeps working on it."}]}]},{"id":"clients","heading":"If you only hire","body":[{"type":"p","content":"Buying never needs an identity check. If you have a refund balance you want to withdraw, you need a payout account, but not an identity check."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('the-7-day-pending-window', 'payouts-and-verification', 1, 'Why earnings show as Pending for 7 days', 'Money you earn — a released payment, a team share, a session or a product sale — is Pending for 7 days as a safety window, then becomes Available to withdraw or spend. Money you put in yourself is available at once.', ARRAY['freelancer', 'team']::text[], ARRAY['freelancer', 'team']::text[], ARRAY['withdraw-your-earnings', 'get-payout-ready', 'accept-and-release-payment']::text[], 8, 'Why are my earnings shown as Pending?', '[{"id":"pending-and-available","heading":"Pending and Available","body":[{"type":"p","content":"Your wallet shows two figures. Available is money you can withdraw or spend on Projective now. Pending is money you''ve earned that is still in its 7-day safety window; it moves to Available on its own when the window ends."},{"type":"table","head":["Money","Pending for 7 days?"],"rows":[["A released escrow payment, including your share of a team payment","Yes"],["A Fair Exit payout or a session payout","Yes"],["A digital product sale","Yes"],["A top-up or card payment you made","No — available at once"],["A refund, a transfer or a returned payout","No — available at once"]],"rowHeaders":true}]},{"id":"why","heading":"Why the window exists","body":[{"type":"p","content":"Card payments can be disputed with the bank for a while after they are made. The window gives Projective time to catch problems before money leaves the platform. If a client''s bank wins a dispute, the money is recovered from that client''s wallet — not from your earnings."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('withdraw-your-earnings', 'payouts-and-verification', 2, 'Withdrawals and minimums', 'Withdraw your Available balance to your verified payout account from your wallet; there is a minimum of about £10 in each currency, and a withdrawal that fails is always returned to your wallet.', ARRAY['freelancer', 'team', 'client']::text[], '{}'::text[], ARRAY['the-7-day-pending-window', 'get-payout-ready', 'fees']::text[], NULL, NULL, '[{"id":"how-to-withdraw","heading":"How to withdraw","body":[{"type":"p","content":["Open your ",{"type":"link","href":"/wallet","text":"wallet"},", choose Withdraw, enter an amount up to your Available balance and pick which of your payout methods to use. Your wallet is debited straight away and the money is sent to your Stripe payout account, which pays your bank on Stripe''s schedule."]}]},{"id":"minimums","heading":"Minimums","body":[{"type":"table","head":["Currency","Minimum"],"rows":[["GBP · USD · EUR · CHF","10.00"],["CAD · SGD","15.00"],["AUD","20.00"],["AED","45.00"],["JPY","¥2,000"],["INR","₹1,000"],["ZAR","R200"],["NGN","₦20,000"],["Any other currency","1,000 of its smallest unit"]],"caption":"The smallest withdrawal in each currency","rowHeaders":true}]},{"id":"if-something-goes-wrong","heading":"If something goes wrong","body":[{"type":"list","items":["If Stripe refuses the withdrawal, the money is credited straight back to your wallet.","A withdrawal is never left in limbo: one whose confirmation is lost is finished, re-sent or returned to your wallet within minutes.","If your bank turns the payout down, you''re told and asked to update your bank details."]},{"type":"callout","tone":"note","body":[{"type":"p","content":"Earnings can only be withdrawn by someone who is payout-ready. A client taking out a refund balance needs a payout account but no identity check."}]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('business-verification-kyb', 'payouts-and-verification', 3, 'Verify a business (KYB)', 'A business is verified through Stripe with its registration details and the people who own it; it needs this before it can fund work or buy from its shared wallet.', ARRAY['business']::text[], ARRAY['business']::text[], ARRAY['create-a-business', 'business-wallet-and-spending-limits', 'paying-by-card-and-currencies']::text[], NULL, NULL, '[{"id":"what-it-is","heading":"What KYB checks","body":[{"type":"p","content":"Know Your Business is the company version of an identity check. Stripe asks for the business''s registration documents and confirms who ultimately owns or controls it. Projective keeps only Stripe''s reference to the check, never the documents."}]},{"id":"who-can-do-it","heading":"Who can do it","body":[{"type":"p","content":"Verification lives in the business console''s Verification view, which opens to the owner — and to an admin the owner has given the billing right. Once verification is under way, the business''s legal name, registration number and corporate email are frozen, because an identity that could change after it was checked would prove nothing."}]},{"id":"what-it-unlocks","heading":"What it unlocks","body":[{"type":"list","items":["Paying for work and buying from the business wallet.","Choosing Invoice at checkout, on a business set up for monthly invoicing."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('create-a-team', 'teams-and-businesses', 0, 'Create a team and split earnings', 'Freelancers can form a team with just a name and a @handle, invite members, and agree how earnings are split; every payment to the team is divided automatically when it is released.', ARRAY['team', 'freelancer']::text[], ARRAY['team']::text[], ARRAY['get-payout-ready', 'invite-people-to-a-stage', 'the-7-day-pending-window']::text[], NULL, NULL, '[{"id":"start-a-team","heading":"Start a team","body":[{"type":"p","content":"Teams are for freelancers: you need a freelancer profile and to be payout-ready. Create one from Teams with a display name and a unique @handle — that''s all. It starts as a draft, and you add branding, roles, members and the earnings split afterwards in its settings. No company registration or joint bank account is needed."}]},{"id":"taking-work","heading":"Taking work as a team","body":[{"type":"list","items":["A team must be published and have at least two members before it can apply to projects.","It applies through a member who is allowed to commit it to work, and uses the team''s own proposal allowance.","It is seated on a stage only when every member who receives a share of its earnings is payout-ready."]}]},{"id":"splitting-earnings","heading":"Splitting earnings","body":[{"type":"p","content":"When a stage''s payment is released to the team, it is divided at once between the team vault and members'' own wallets, following the team''s split. Each share then clears the 7-day pending window in its owner''s wallet."},{"type":"table","head":["Split","How it divides","Plan"],"rows":[["Co-op","Equal shares for every member, after the vault''s cut.","Every team"],["Finder''s fee","A fixed percentage to the member who found the project, the rest shared.","Pro Team"],["Benevolent dictator","Everything to the team vault, shared out by an admin.","Pro Team"]],"rowHeaders":true},{"type":"p","content":"Saving a new split replaces the active one and keeps the old one as history. A team that moves back to the free plan keeps using the split it already has until it saves a new one."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('create-a-business', 'teams-and-businesses', 1, 'Create a business and invite your colleagues', 'Any adult account can create a business with a name and a @handle; colleagues join as Owner, Admin or Member, and custom roles decide exactly who may hire, approve work and spend.', ARRAY['business', 'client']::text[], ARRAY['business']::text[], ARRAY['business-wallet-and-spending-limits', 'business-verification-kyb', 'invite-people-to-a-stage']::text[], NULL, NULL, '[{"id":"create-one","heading":"Create one","body":[{"type":"p","content":"Choose Create Business from Businesses and give it a display name and a unique @handle. It starts as a draft; you add its legal name, logo, billing details and members afterwards. Acting as a business is always acting as a client, so the business view shows no selling tools."},{"type":"p","content":"A business can be public (listed in the directory), unlisted, or invite-only. How many businesses you can own depends on your plan; how many you can join is never limited."}]},{"id":"roles","heading":"Roles","body":[{"type":"dl","items":[{"term":"Owner","definition":"Everything, including withdrawing from the business wallet, billing, verification and archiving the business. One per business."},{"term":"Admin","definition":"Manages the wallet, sets spending limits and invites or removes members — everything except withdrawing, billing, verification and archiving, unless the owner grants them."},{"term":"Member","definition":"Sees the business''s projects, comments, asks for free revisions and can add money to the wallet. Anything more comes from a custom role."}]},{"type":"p","content":"Custom roles grant exactly what they list. Project Manager (creates projects, approves work, releases payments) and Observer (view only) are offered as starting points."}]},{"id":"one-permission-per-act","heading":"One permission for each act","body":[{"type":"p","content":"Hiring and approving work that releases payment need the hiring permission; creating a project billed to the business needs the project permission; buying from the business wallet needs the purchasing permission; and funding escrow needs the right to spend from the wallet. A member who created a project keeps the authority to hire and approve on it."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('business-wallet-and-spending-limits', 'teams-and-businesses', 2, 'The business wallet, spending limits and approvals', 'A business pays from one shared wallet that starts at zero; on Business Pro, members can be given spending limits, and payments over a limit or threshold wait for someone else''s approval.', ARRAY['business']::text[], ARRAY['business']::text[], ARRAY['create-a-business', 'business-verification-kyb', 'needs-funding']::text[], NULL, NULL, '[{"id":"the-shared-wallet","heading":"The shared wallet","body":[{"type":"p","content":"The business wallet holds the money every member spends on the business''s behalf, so nobody needs the company card for each payment. It starts at zero and only ever holds real money: top-ups, refunds and transfers in."},{"type":"p","content":"When the wallet can''t cover a payment, the payment is refused — it is never topped up from a member''s own card — and members who can add money see Contribute."}]},{"id":"limits-and-approvals","heading":"Spending limits and approvals","body":[{"type":"p","content":"On Business Pro, each member can have a spending limit, and the wallet can have an approval threshold. A payment over the member''s limit, or at or above the threshold, becomes a spend request instead of going through."},{"type":"list","items":["Someone with the approve-spend permission — never the person asking — approves or rejects it.","An approval covers exactly the payment it was for, and is used once.","A request nobody answers expires after 7 days."]},{"type":"p","content":"Every payment is counted against the member who made it. Payments nobody makes by hand — a claim, an automatic stage funding — count against the project''s owner."}]},{"id":"staying-topped-up","heading":"Staying topped up","body":[{"type":"list","items":["Set a balance floor to warn everyone who can add money when the wallet drops below it.","Add a floor top-up that charges a saved card each time the balance drops below the floor.","Choose what happens when a ticket needs funding: tell the project owner, add it to their basket, or pay it from the wallet as soon as the money is there."]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('signing-in', 'account-and-security', 0, 'Signing in and staying signed in', 'Sign in with your email or @handle and your password, or with Google; Keep me signed in keeps you signed in on that device for 30 days, and a forgotten password is reset with a 6-digit code sent by email.', ARRAY['client', 'freelancer', 'team', 'business']::text[], '{}'::text[], ARRAY['change-your-handle-or-close-your-account', 'contact-details-in-messages', 'age-requirements']::text[], NULL, NULL, '[{"id":"signing-in","heading":"Signing in","body":[{"type":"p","content":"On the sign-in page, enter either your email address or your @handle, then your password. If either is wrong, the message doesn''t say which — that stops anyone using the form to find out whether an account exists."},{"type":"p","content":[{"type":"strong","text":"Keep me signed in"}," is on by default and keeps you signed in on that device for 30 days between visits. Untick it on a shared computer: you''re then signed out when the browser closes."]}]},{"id":"other-ways-in","heading":"Other ways in","body":[{"type":"p","content":["You can sign in with Google, and connect other accounts in ",{"type":"link","href":"/settings/account","text":"Settings → Account"}," where they are available. You can disconnect a sign-in method as long as another one remains."]}]},{"id":"forgotten-password","heading":"A forgotten password","body":[{"type":"list","ordered":true,"items":["Choose Forgot password on the sign-in page and enter your email.","We email you a 6-digit code. The page looks the same whether or not the address has an account.","Enter the code and your new password, then sign in."]},{"type":"p","content":"New accounts confirm their email the same way, with a 6-digit code — or with the link in the email."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('age-requirements', 'account-and-security', 1, 'Age requirements and limited accounts', 'You must be at least 13 to have an account. From 13 to 17 you have a limited account — explore, build a private profile and run personal projects, but no buying, selling or payments — and everything unlocks on your 18th birthday.', ARRAY['client', 'freelancer']::text[], '{}'::text[], ARRAY['signing-in', 'contact-details-in-messages', 'create-a-project']::text[], NULL, NULL, '[{"id":"the-three-ages","heading":"The three age groups","body":[{"type":"table","head":["Age","Account","What it means"],"rows":[["Under 13","Not allowed","No account is created, and nothing about the attempt is kept."],["13 to 17","Limited account","Explore, read articles, build a private profile and portfolio, and run personal projects."],["18 and over","Full account","Everything, subject to the usual identity checks."]],"rowHeaders":true}]},{"id":"limited-accounts","heading":"What a limited account can''t do","body":[{"type":"list","items":["Buy, sell, book calls or sessions, fund or claim paid work, or publish listings.","Have a wallet or a payout account.","Create or join a team, business or enterprise.","Have a public profile, or show its location and local time to others.","Message people who don''t follow it back."]},{"type":"p","content":"Instead of showing these and refusing, Projective leaves them out, and Settings → Account shows the account as a Limited account. A limited account isn''t tracked for personalised discovery, and its searches are logged anonymously."}]},{"id":"birthdays","heading":"Birthdays","body":[{"type":"p","content":"Your age changes automatically on your birthday, in your own time zone. A personal project you created while under 18 stays personal; start a new project when you want to hire."}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('contact-details-in-messages', 'account-and-security', 2, 'Why contact details are hidden in messages', 'While a project is under way, email addresses, phone numbers, payment links and payment handles in its messages are replaced with placeholders such as [email hidden]; the restriction lifts once the project''s final payment is released.', ARRAY['client', 'freelancer', 'team', 'business']::text[], '{}'::text[], ARRAY['what-is-escrow', 'signing-in', 'how-disputes-are-decided']::text[], NULL, NULL, '[{"id":"what-is-hidden","heading":"What is hidden, and where","body":[{"type":"p","content":"From the first proposal until the project''s final payment is released, messages in its rooms — and direct messages between people negotiating or working on it — are checked as they are sent. Anything that looks like contact or payment details is replaced:"},{"type":"list","items":[{"content":[{"type":"code","text":"[email hidden]"}," — an email address"]},{"content":[{"type":"code","text":"[phone hidden]"}," — a phone number"]},{"content":[{"type":"code","text":"[link hidden]"}," — a payment or messaging link, such as PayPal or WhatsApp"]},{"content":[{"type":"code","text":"[handle hidden]"}," — a payment handle, such as a $cashtag"]}]},{"type":"p","content":"Nobody can switch this off for a project, because it protects both sides: work and payment stay where escrow can protect them."}]},{"id":"the-unlock","heading":"When it lifts","body":[{"type":"p","content":"When a project''s final payment is released, the restriction lifts for that project''s conversations. Swapping details then is welcome — many good working relationships start here."},{"type":"callout","tone":"warning","title":"Public pages never unlock","body":[{"type":"p","content":"Your profile, service and product listings and public project briefs must never include bank or card details, payment links or direct contact details — at any time."}]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL),
    ('change-your-handle-or-close-your-account', 'account-and-security', 3, 'Change your handle or close your account', 'You can change your @handle twice within three days before it locks for 90 days; closing your account hides your profile at once and erases your personal data after 30 days, unless you cancel.', ARRAY['client', 'freelancer', 'team', 'business']::text[], '{}'::text[], ARRAY['signing-in', 'withdraw-your-earnings', 'age-requirements']::text[], NULL, NULL, '[{"id":"your-handle","heading":"Your @handle","body":[{"type":"p","content":"Change it in Settings → Account. You can change it twice within three days — enough to fix a typo — and after the second change it is locked for 90 days. Settings tells you how many changes are left and, once locked, when it unlocks."},{"type":"p","content":"A handle you give up is kept for you for 90 days: nobody else can take it, and you can take it back."}]},{"id":"stop-freelancing","heading":"Going back to hiring only","body":[{"type":"p","content":"A freelancer can switch to client only, after typing CONFIRM. Selling stops at once and your listings are taken down; your freelancer profile is erased after 90 days, and becoming a freelancer again within those 90 days restores everything. Reviews and money records are kept, because other people rely on them."}]},{"id":"close-your-account","heading":"Closing your account","body":[{"type":"p","content":"Delete your account from Settings → Account, after typing CONFIRM. Your profile is hidden straight away and your personal data is erased after 30 days; until then you can cancel from Settings. Records of money that moved are kept, anonymised, for as long as the law requires."},{"type":"callout","tone":"note","title":"Finish up first","body":[{"type":"p","content":"You can''t close your account, or stop freelancing, while money is held in escrow for you, you have live work, or your wallet still holds money. Closing your account also waits until no project you own is running and you no longer own a team, business or enterprise."}]}]}]'::jsonb, '2026-10-17'::date, '2026-10-17'::date, NULL)
